pub struct Order { id: OrderId, customer: CustomerId, lines: Vec<Line>, total: Money }

impl Order {
    pub fn open(customer: CustomerId) -> Self {
        Order { id: OrderId::new(), customer, lines: Vec::new(), total: Money::ZERO }
    }

    pub fn add_line(&mut self, line: Line) -> Result<(), OrderError> {
        let next = self.total + line.price();
        if next > LIMIT { return Err(OrderError::LimitExceeded); }
        self.total = next;
        self.lines.push(line);
        Ok(())
    }
}
